 public static object Main(){if(!Application.isPlaying)throw new Exception("Play required");Application.runInBackground=true;EditorApplication.isPaused=false;EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Focus();var owner=UnityEngine.Object.FindAnyObjectByType<EchoSphere.Runtime.EchoSphereRuntime>();var a=owner.GetType().Assembly;var ct=a.GetType("EchoSphere.Presentation.NativePausedBackdropCache");var et=a.GetType("EchoSphere.Presentation.NativeEngineBackdrop");var go=new GameObject("Frozen pause pixel acceptance");var panel=ScriptableObject.CreateInstance<PanelSettings>();panel.themeStyleSheet=Resources.Load<ThemeStyleSheet>("EchoSphere/SourceUiTheme");panel.scale=1;panel.sortingOrder=100000;var doc=go.AddComponent<UIDocument>();doc.panelSettings=panel;doc.sortingOrder=100000;var root=doc.rootVisualElement;root.style.position=Position.Absolute;root.style.left=root.style.top=root.style.right=root.style.bottom=0;root.style.backgroundColor=new Color(.06f,.15f,.28f,1);
 VisualElement Rect(VisualElement parent,string name,float x,float y,float w,float h,Color color){var e=new VisualElement{name=name};e.style.position=Position.Absolute;e.style.left=x;e.style.top=y;e.style.width=w;e.style.height=h;e.style.backgroundColor=color;parent.Add(e);return e;}
 for(int i=0;i<8;i++)Rect(root,"fixed-world-"+i,i*Screen.width/8,0,Screen.width/16,Screen.height,i%2==0?new Color(.20f,.70f,.90f):new Color(.72f,.24f,.50f));Rect(root,"orientation-marker",10,10,Screen.width*.18f,Screen.height*.22f,Color.yellow);var text=new Label("Frozen game layer");text.style.fontSize=32;text.style.color=Color.white;text.style.position=Position.Absolute;text.style.left=35;text.style.top=40;root.Add(text);
 var overlay=new VisualElement{name="test-pause-overlay"};overlay.style.position=Position.Absolute;overlay.style.left=overlay.style.top=overlay.style.right=overlay.style.bottom=0;overlay.style.backgroundColor=new Color(0,0,0,.35f);root.Add(overlay);var shell=Rect(overlay,"live-pause-menu",Screen.width*.25f,Screen.height*.25f,Screen.width*.5f,Screen.height*.5f,new Color(.04f,.07f,.14f,.9f));shell.Add(new Label("Pause - live controls"));var button=new Button(){text="Still interactive"};shell.Add(button);int clicks=0;button.clicked+=()=>clicks++;
 object Call(object o,string n,params object[] args)=>o.GetType().GetMethod(n,F).Invoke(o,args);var effect=Activator.CreateInstance(et,F,null,new object[]{overlay,4f},null);var cache=Activator.CreateInstance(ct,F,null,new object[]{owner,overlay,4f,new Action<bool>(v=>Call(effect,"SetVisible",v))},null);var disable=ct.GetField("DisableForValidation",F);disable.SetValue(null,true);int phase=0,frames=0,last=-1,checks=0;double started=EditorApplication.timeSinceStartup;Texture2D before=null;bool capturing=false,done=false;double mean=0;string dir="Library/paused-backdrop-test";Directory.CreateDirectory(dir);EditorApplication.CallbackFunction tick=null;
 void Finish(string status){if(done)return;done=true;EditorApplication.update-=tick;disable.SetValue(null,false);((IDisposable)cache).Dispose();((IDisposable)effect).Dispose();if(before!=null)UnityEngine.Object.DestroyImmediate(before);UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(panel);File.WriteAllText(dir+"/result.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status,checks,meanRgb=mean},Newtonsoft.Json.Formatting.Indented));UnityEditor.SessionState.SetString("EchoPausedBackdropAcceptance",status);}
 IEnumerator Capture(bool baseline){yield return new WaitForEndOfFrame();var pic=ScreenCapture.CaptureScreenshotAsTexture();if(baseline){before=pic;File.WriteAllBytes(dir+"/live.png",pic.EncodeToPNG());disable.SetValue(null,false);Call(cache,"Reset");phase=1;frames=0;}else{File.WriteAllBytes(dir+"/cached.png",pic.EncodeToPNG());var x=before.GetPixels32();var y=pic.GetPixels32();if(x.Length!=y.Length){UnityEngine.Object.DestroyImmediate(pic);Finish("FAIL viewport changed");yield break;}long sum=0;for(int i=0;i<x.Length;i++)sum+=Math.Abs(x[i].r-y[i].r)+Math.Abs(x[i].g-y[i].g)+Math.Abs(x[i].b-y[i].b);mean=sum/(double)(x.Length*3);UnityEngine.Object.DestroyImmediate(pic);if(mean>2){Finish("FAIL pixels differ "+mean);yield break;}checks++;phase=2;frames=0;}capturing=false;}
 tick=()=>{try{if(done)return;if(!Application.isPlaying||EditorApplication.timeSinceStartup-started>45){Finish("FAIL deadline or Play ended");return;}if(last==Time.frameCount)return;last=Time.frameCount;Call(cache,"Update",true,true,1f,0);frames++;if(phase==0&&frames>=8&&!capturing){capturing=true;owner.StartCoroutine(Capture(true));}else if(phase==1&&(bool)ct.GetProperty("Ready",F).GetValue(cache)&&frames>=8&&!capturing){capturing=true;owner.StartCoroutine(Capture(false));}else if(phase==2&&frames>=60){if((int)ct.GetProperty("BakeCount",F).GetValue(cache)!=1)throw new Exception("unchanged pause reblurs");checks++;Call(cache,"Update",true,true,1f,1);if((bool)ct.GetProperty("Ready",F).GetValue(cache))throw new Exception("changed key retained stale cache");checks++;Finish("PASS frozen pause pixels, one bake over60 frames and dynamic-key fallback");}}catch(Exception e){Finish("FAIL "+e.GetBaseException().Message);}};EditorApplication.update+=tick;return new{status="RUNNING",output=Path.GetFullPath(dir+"/result.json")};
 }
}
